      "label": "not_met",
      "reason": "Svaret mangler det første kritiske element: at dokumentationen skal være relevant og aktuel og beskrive den varige funktionsnedsættelses art og grad. Det nævner hverken varighed, art/grad, aktualitet eller udredningsforløb. Det fremgår heller ikke, at funktionsnedsættelsen skal være varig. De øvrige elementer er dækket."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvad den lægelige dokumentation skal beskrive, med en punktliste svarende til kilden."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som vejledning, afsnit eller bekendtgørelsesparagraf."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så kildestøtten kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Svaret tilføjer ingen regel, betingelse eller retsvirkning, der mangler støtte i de frosne kilder. Alle punkter findes i vejledningens afsnit 4.2."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Forbeholdene 'hvis der er stillet en', 'hvis der er planlagt en' og 'hvis muligt' er bevaret. Tilgængelighed i journalen eller anden eksisterende dokumentation er nævnt som forbehold. Aktualitetskravet mangler, men det vedrører primært C02, ikke bevarelsen af forbehold."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er en enkel og konsistent opremsning, og afslutningen om journalen følger af listen."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "'Skal' bruges om de beskrivende elementer, og de betingede punkter er markeret som betingede. Det skaber ingen urigtig absolutisering. Svaret siger, at oplysningerne skal fremgå af den dokumentation, som den uddannelsessøgende har tilgængeligt, hvilket i store træk svarer til kilden."
    }
  },
  "xhaile_coverage": {
    "A39": {
      "label": "yes",
      "reason": "Punkt 1 nævner diagnosen med forbeholdet 'hvis der er stillet en'."
    },
    "A41": {
      "label": "yes",
      "reason": "Punkt 2 nævner beskrivelse af sygdoms- og behandlingsforløbet."
    },
    "A42": {
      "label": "yes",
      "reason": "Punkt 2 dækker behandlingsforløbet, og punkt 4 dækker den nuværende behandling."
    },
    "A45": {
      "label": "yes",
      "reason": "Punkt 5 nævner planlagt behandling med forbeholdet 'hvis der er planlagt en'."
    },
    "A47": {
      "label": "yes",
      "reason": "Punkt 6 nævner påvirkning af erhvervsevnen med forbeholdet 'hvis muligt'."
    }
  },
  "overall_notes": "Svaret gengiver korrekt de seks punkter i vejledningens afsnit 4.2 med forbehold. Det udelader dog kravet om, at dokumentationen skal være relevant og aktuel og beskrive den varige funktionsnedsættelses art og grad, samt udredningsforløbet. Det angiver heller ingen kilde, så C04 er not_met og C05 og C06 er not_assessable."
}

